const RecommendationEngine = {
  getRecommendations(dressId, limit = 4) {
    const key = `dress_${dressId}`;
    const matches = StyleSimilarityMatrix[key] || {};
    return Object.keys(matches).slice(0, limit);
  },
  calculateOccasionScore(dress, occasion) {
    if (!dress || !occasion) return 0.5;
    return dress.category.toLowerCase() === occasion.toLowerCase() ? 0.95 : 0.6;
  }
};

if (typeof window !== 'undefined') { window.RecommendationEngine = RecommendationEngine; }
